<section data-page-title="Service Requests" data-page-script="service_requests.js"><div class="page-intro"><span class="eyebrow">In-stay help</span><h2>Service requests</h2><p>Create and track requests for active stays.</p></div><div id="alertBox" class="alert"></div><div class="grid grid-2"><div class="card"><h3>Create Request</h3><form id="requestForm" class="form-grid one"><div class="form-group"><label>Active Booking</label><select class="select" name="booking_id" id="activeBookingSelect" required><option value="">Loading active bookings...</option></select></div><div class="form-group"><label>Service Type</label><select class="select" name="service_type" required><option value="extra_bed">Extra Bed</option><option value="toiletries">Toiletries</option><option value="laundry">Laundry</option><option value="room_service">Room Service</option><option value="other">Other</option></select></div><div class="form-group"><label>Description</label><textarea class="input" name="description" rows="4" required></textarea></div><button class="btn btn-gradient" type="submit">Submit Request</button></form></div><div class="card"><div class="section-head"><div><h3>My Requests</h3><p>Track current and past requests</p></div><button class="btn btn-light" id="refreshBtn">Refresh</button></div><div class="table-wrap"><table><thead><tr><th>Booking</th><th>Type</th><th>Description</th><th>Status</th></tr></thead><tbody id="requestTable"><tr><td colspan="4" class="empty">Loading...</td></tr></tbody></table></div></div></div></section>